#nullable enable // autogenerated

using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using PVZEngine.Timing;
using PVZEngine.Tools.Timing;

namespace MVZ2.GameContent.Buffs.Entities
{
    [AutoBuffDefinition(VanillaBuffNames.Enemy.blackholeDragged)]
    public class BlackholeDraggedBuff : BuffDefinition
    {
        public BlackholeDraggedBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(VanillaEnemyProps.NO_ALIGN_TO_LANE, true));
        }
        public override void PostAdd(Buff buff)
        {
            base.PostAdd(buff);
            buff.SetProperty(PROP_TIMER, new FrameTimer(2));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var timer = buff.GetProperty<FrameTimer>(PROP_TIMER);
            if (timer.RunToExpiredOrNull())
            {
                buff.Remove();
                return;
            }
            else
            {
                var entity = buff.GetEntity();
                if (entity != null)
                {
                    entity.StopChangingLane();
                }
            }
        }
        public static void Extend(Entity entity)
        {
            var buff = entity.GetFirstBuff<BlackholeDraggedBuff>();
            if (buff == null)
            {
                buff = entity.AddBuff<BlackholeDraggedBuff>();
            }
            Extend(buff);
        }
        public static void Extend(Buff buff)
        {
            var timer = buff.GetProperty<FrameTimer>(PROP_TIMER);
            if (timer != null)
            {
                timer.Reset();
            }
        }
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("Timer");
    }
}
